INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100101, 1, 1, "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", 0, "vo_empress_100101_001", "ヒヨリ", "vo_empress_100101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100103, 2, 1, "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", 0, "vo_empress_100101_002", "ヒヨリ", "vo_empress_100101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100103, 3, 1, "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", 0, "vo_empress_100101_003", "ヒヨリ", "vo_empress_100101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100102, 4, 1, "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", 100101, "vo_empress_100101_004", "ヒヨリ", "vo_empress_100101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100203, 5, 1, "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", 0, "vo_empress_100201_001", "ユイ", "vo_empress_100201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100203, 6, 1, "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", 0, "vo_empress_100201_002", "ユイ", "vo_empress_100201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100203, 7, 1, "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", 0, "vo_empress_100201_003", "ユイ", "vo_empress_100201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100202, 8, 1, "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", 100201, "vo_empress_100201_004", "ユイ", "vo_empress_100201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100301, 9, 1, "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", 0, "vo_empress_100301_001", "レイ", "vo_empress_100301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100303, 10, 1, "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", 0, "vo_empress_100301_002", "レイ", "vo_empress_100301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100303, 11, 1, "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", 0, "vo_empress_100301_003", "レイ", "vo_empress_100301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100302, 12, 1, "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", 100301, "vo_empress_100301_004", "レイ", "vo_empress_100301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100401, 13, 1, "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", 0, "vo_empress_100401_001", "ミソギ", "vo_empress_100401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100401, 14, 1, "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", 0, "vo_empress_100401_002", "ミソギ", "vo_empress_100401_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100403, 15, 1, "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", 0, "vo_empress_100401_003", "ミソギ", "vo_empress_100401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100402, 16, 1, "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", 100401, "vo_empress_100401_004", "ミソギ", "vo_empress_100401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100501, 17, 1, "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", 0, "vo_empress_100501_001", "マツリ", "vo_empress_100501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100501, 18, 1, "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", 0, "vo_empress_100501_002", "マツリ", "vo_empress_100501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100503, 19, 1, "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", 0, "vo_empress_100501_003", "マツリ", "vo_empress_100501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100502, 20, 1, "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", 100501, "vo_empress_100501_004", "マツリ", "vo_empress_100501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100603, 21, 1, "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", 0, "vo_empress_100601_001", "アカリ", "vo_empress_100601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100601, 22, 1, "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", 0, "vo_empress_100601_002", "アカリ", "vo_empress_100601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100603, 23, 1, "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", 0, "vo_empress_100601_003", "アカリ", "vo_empress_100601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100602, 24, 1, "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", 100601, "vo_empress_100601_004", "アカリ", "vo_empress_100601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100701, 25, 1, "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", 0, "vo_empress_100701_001", "ミヤコ", "vo_empress_100701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100702, 26, 1, "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", 0, "vo_empress_100701_002", "ミヤコ", "vo_empress_100701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100703, 27, 1, "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", 0, "vo_empress_100701_003", "ミヤコ", "vo_empress_100701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100702, 28, 1, "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", 100701, "vo_empress_100701_004", "ミヤコ", "vo_empress_100701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100801, 29, 1, "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", 0, "vo_empress_100801_001", "ユキ", "vo_empress_100801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100801, 30, 1, "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", 0, "vo_empress_100801_002", "ユキ", "vo_empress_100801_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100801, 31, 1, "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", 0, "vo_empress_100801_003", "ユキ", "vo_empress_100801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100802, 32, 1, "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", 100801, "vo_empress_100801_004", "ユキ", "vo_empress_100801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100901, 33, 1, "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", 0, "vo_empress_100901_001", "アンナ", "vo_empress_100901_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 100903, 34, 1, "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", 0, "vo_empress_100901_002", "アンナ", "vo_empress_100901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 100903, 35, 1, "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", 0, "vo_empress_100901_003", "アンナ", "vo_empress_100901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 100902, 36, 1, "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", 100901, "vo_empress_100901_004", "アンナ", "vo_empress_100901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101001, 37, 1, "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", 0, "vo_empress_101001_001", "マホ", "vo_empress_101001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101001, 38, 1, "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", 0, "vo_empress_101001_002", "マホ", "vo_empress_101001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101003, 39, 1, "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", 0, "vo_empress_101001_003", "マホ", "vo_empress_101001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101002, 40, 1, "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", 101001, "vo_empress_101001_004", "マホ", "vo_empress_101001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101101, 41, 1, "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", 0, "vo_empress_101101_001", "リノ", "vo_empress_101101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101101, 42, 1, "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", 0, "vo_empress_101101_002", "リノ", "vo_empress_101101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101103, 43, 1, "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", 0, "vo_empress_101101_003", "リノ", "vo_empress_101101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101102, 44, 1, "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", 101101, "vo_empress_101101_004", "リノ", "vo_empress_101101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101201, 45, 1, "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", 0, "vo_empress_101201_001", "ハツネ", "vo_empress_101201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101202, 46, 1, "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", 0, "vo_empress_101201_002", "ハツネ", "vo_empress_101201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101203, 47, 1, "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", 0, "vo_empress_101201_003", "ハツネ", "vo_empress_101201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101202, 48, 1, "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", 101201, "vo_empress_101201_004", "ハツネ", "vo_empress_101201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101301, 49, 1, "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", 0, "vo_empress_101301_001", "ナナカ", "vo_empress_101301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101301, 50, 1, "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", 0, "vo_empress_101301_002", "ナナカ", "vo_empress_101301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101303, 51, 1, "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", 0, "vo_empress_101301_003", "ナナカ", "vo_empress_101301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101302, 52, 1, "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", 101301, "vo_empress_101301_004", "ナナカ", "vo_empress_101301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101401, 53, 1, "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", 0, "vo_empress_101401_001", "カスミ", "vo_empress_101401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101401, 54, 1, "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", 0, "vo_empress_101401_002", "カスミ", "vo_empress_101401_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101403, 55, 1, "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", 0, "vo_empress_101401_003", "カスミ", "vo_empress_101401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101402, 56, 1, "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", 101401, "vo_empress_101401_004", "カスミ", "vo_empress_101401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101501, 57, 1, "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", 0, "vo_empress_101501_001", "ミサト", "vo_empress_101501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101501, 58, 1, "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", 0, "vo_empress_101501_002", "ミサト", "vo_empress_101501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101501, 59, 1, "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", 0, "vo_empress_101501_003", "ミサト", "vo_empress_101501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101502, 60, 1, "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", 101501, "vo_empress_101501_004", "ミサト", "vo_empress_101501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101601, 61, 1, "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", 0, "vo_empress_101601_001", "スズナ", "vo_empress_101601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101601, 62, 1, "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", 0, "vo_empress_101601_002", "スズナ", "vo_empress_101601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101601, 63, 1, "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", 0, "vo_empress_101601_003", "スズナ", "vo_empress_101601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101602, 64, 1, "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", 101601, "vo_empress_101601_004", "スズナ", "vo_empress_101601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101701, 65, 1, "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", 0, "vo_empress_101701_001", "カオリ", "vo_empress_101701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101701, 66, 1, "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", 0, "vo_empress_101701_002", "カオリ", "vo_empress_101701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101703, 67, 1, "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", 0, "vo_empress_101701_003", "カオリ", "vo_empress_101701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101702, 68, 1, "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", 101701, "vo_empress_101701_004", "カオリ", "vo_empress_101701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101801, 69, 1, "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", 0, "vo_empress_101801_001", "イオ", "vo_empress_101801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 101801, 70, 1, "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", 0, "vo_empress_101801_002", "イオ", "vo_empress_101801_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 101803, 71, 1, "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", 0, "vo_empress_101801_003", "イオ", "vo_empress_101801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 101802, 72, 1, "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", 101801, "vo_empress_101801_004", "イオ", "vo_empress_101801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102003, 73, 1, "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", 0, "vo_empress_102001_001", "ミミ", "vo_empress_102001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102003, 74, 1, "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", 0, "vo_empress_102001_002", "ミミ", "vo_empress_102001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102003, 75, 1, "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", 0, "vo_empress_102001_003", "ミミ", "vo_empress_102001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102002, 76, 1, "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", 102001, "vo_empress_102001_004", "ミミ", "vo_empress_102001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102101, 77, 1, "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", 0, "vo_empress_102101_001", "クルミ", "vo_empress_102101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102101, 78, 1, "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", 0, "vo_empress_102101_002", "クルミ", "vo_empress_102101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102101, 79, 1, "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", 0, "vo_empress_102101_003", "クルミ", "vo_empress_102101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102102, 80, 1, "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", 102101, "vo_empress_102101_004", "クルミ", "vo_empress_102101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102201, 81, 1, "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", 0, "vo_empress_102201_001", "ヨリ", "vo_empress_102201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102201, 82, 1, "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", 0, "vo_empress_102201_002", "ヨリ", "vo_empress_102201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102203, 83, 1, "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", 0, "vo_empress_102201_003", "ヨリ", "vo_empress_102201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102202, 84, 1, "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", 102201, "vo_empress_102201_004", "ヨリ", "vo_empress_102201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102301, 85, 1, "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", 0, "vo_empress_102301_001", "アヤネ", "vo_empress_102301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102303, 86, 1, "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", 0, "vo_empress_102301_002", "アヤネ", "vo_empress_102301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102303, 87, 1, "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", 0, "vo_empress_102301_003", "アヤネ", "vo_empress_102301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102302, 88, 1, "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", 102301, "vo_empress_102301_004", "アヤネ", "vo_empress_102301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102503, 89, 1, "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", 0, "vo_empress_102501_001", "スズメ", "vo_empress_102501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102503, 90, 1, "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", 0, "vo_empress_102501_002", "スズメ", "vo_empress_102501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102503, 91, 1, "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", 0, "vo_empress_102501_003", "スズメ", "vo_empress_102501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102502, 92, 1, "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", 102501, "vo_empress_102501_004", "スズメ", "vo_empress_102501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102603, 93, 1, "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", 0, "vo_empress_102601_001", "リン", "vo_empress_102601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102603, 94, 1, "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", 0, "vo_empress_102601_002", "リン", "vo_empress_102601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102603, 95, 1, "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", 0, "vo_empress_102601_003", "リン", "vo_empress_102601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102602, 96, 1, "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", 102601, "vo_empress_102601_004", "リン", "vo_empress_102601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102701, 97, 1, "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", 0, "vo_empress_102701_001", "エリコ", "vo_empress_102701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102701, 98, 1, "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", 0, "vo_empress_102701_002", "エリコ", "vo_empress_102701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102703, 99, 1, "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", 0, "vo_empress_102701_003", "エリコ", "vo_empress_102701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102702, 100, 1, "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", 102701, "vo_empress_102701_004", "エリコ", "vo_empress_102701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102801, 101, 1, "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", 0, "vo_empress_102801_001", "サレン", "vo_empress_102801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 102801, 102, 1, "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 0, "vo_empress_102801_002", "サレン", "vo_empress_102801_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102803, 103, 1, "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", 0, "vo_empress_102801_003", "サレン", "vo_empress_102801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102802, 104, 1, "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", 102801, "vo_empress_102801_004", "サレン", "vo_empress_102801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102903, 105, 1, "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", 0, "vo_empress_102901_001", "ノゾミ", "vo_empress_102901_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 102903, 106, 1, "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", 0, "vo_empress_102901_002", "ノゾミ", "vo_empress_102901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 102903, 107, 1, "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", 0, "vo_empress_102901_003", "ノゾミ", "vo_empress_102901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 102901, 108, 1, "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", 102901, "vo_empress_102901_004", "ノゾミ", "vo_empress_102901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103001, 109, 1, "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", 0, "vo_empress_103001_001", "ニノン", "vo_empress_103001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103001, 110, 1, "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", 0, "vo_empress_103001_002", "ニノン", "vo_empress_103001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103003, 111, 1, "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", 0, "vo_empress_103001_003", "ニノン", "vo_empress_103001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103002, 112, 1, "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", 103001, "vo_empress_103001_004", "ニノン", "vo_empress_103001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103101, 113, 1, "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", 0, "vo_empress_103101_001", "シノブ", "vo_empress_103101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103101, 114, 1, "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", 0, "vo_empress_103101_002", "シノブ", "vo_empress_103101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103103, 115, 1, "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", 0, "vo_empress_103101_003", "シノブ", "vo_empress_103101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103101, 116, 1, "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", 103101, "vo_empress_103101_004", "シノブ", "vo_empress_103101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103201, 117, 1, "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", 0, "vo_empress_103201_001", "アキノ", "vo_empress_103201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103201, 118, 1, "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", 0, "vo_empress_103201_002", "アキノ", "vo_empress_103201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103203, 119, 1, "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", 0, "vo_empress_103201_003", "アキノ", "vo_empress_103201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103202, 120, 1, "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", 103201, "vo_empress_103201_004", "アキノ", "vo_empress_103201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103301, 121, 1, "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", 0, "vo_empress_103301_001", "マヒル", "vo_empress_103301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103301, 122, 1, "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", 0, "vo_empress_103301_002", "マヒル", "vo_empress_103301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103303, 123, 1, "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", 0, "vo_empress_103301_003", "マヒル", "vo_empress_103301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103302, 124, 1, "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", 103301, "vo_empress_103301_004", "マヒル", "vo_empress_103301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103401, 125, 1, "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", 0, "vo_empress_103401_001", "ユカリ", "vo_empress_103401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103401, 126, 1, "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", 0, "vo_empress_103401_002", "ユカリ", "vo_empress_103401_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103403, 127, 1, "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", 0, "vo_empress_103401_003", "ユカリ", "vo_empress_103401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103402, 128, 1, "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", 103401, "vo_empress_103401_004", "ユカリ", "vo_empress_103401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103603, 129, 1, "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", 0, "vo_empress_103601_001", "キョウカ", "vo_empress_103601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103603, 130, 1, "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", 0, "vo_empress_103601_002", "キョウカ", "vo_empress_103601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103601, 131, 1, "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", 0, "vo_empress_103601_003", "キョウカ", "vo_empress_103601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103602, 132, 1, "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", 103601, "vo_empress_103601_004", "キョウカ", "vo_empress_103601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103701, 133, 1, "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", 0, "vo_empress_103701_001", "トモ", "vo_empress_103701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103701, 134, 1, "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", 0, "vo_empress_103701_002", "トモ", "vo_empress_103701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103701, 135, 1, "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", 0, "vo_empress_103701_003", "トモ", "vo_empress_103701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103702, 136, 1, "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", 103701, "vo_empress_103701_004", "トモ", "vo_empress_103701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103801, 137, 1, "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", 0, "vo_empress_103801_001", "シオリ", "vo_empress_103801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 103801, 138, 1, "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", 0, "vo_empress_103801_002", "シオリ", "vo_empress_103801_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 103803, 139, 1, "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", 0, "vo_empress_103801_003", "シオリ", "vo_empress_103801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 103802, 140, 1, "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", 103801, "vo_empress_103801_004", "シオリ", "vo_empress_103801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104001, 141, 1, "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", 0, "vo_empress_104001_001", "アオイ", "vo_empress_104001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104002, 142, 1, "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", 0, "vo_empress_104001_002", "アオイ", "vo_empress_104001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104003, 143, 1, "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", 0, "vo_empress_104001_003", "アオイ", "vo_empress_104001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104002, 144, 1, "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", 104001, "vo_empress_104001_004", "アオイ", "vo_empress_104001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104203, 145, 1, "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", 0, "vo_empress_104201_001", "チカ", "vo_empress_104201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104201, 146, 1, "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", 0, "vo_empress_104201_002", "チカ", "vo_empress_104201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104203, 147, 1, "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", 0, "vo_empress_104201_003", "チカ", "vo_empress_104201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104201, 148, 1, "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", 104201, "vo_empress_104201_004", "チカ", "vo_empress_104201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104301, 149, 1, "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", 0, "vo_empress_104301_001", "マコト", "vo_empress_104301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104301, 150, 1, "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", 0, "vo_empress_104301_002", "マコト", "vo_empress_104301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104303, 151, 1, "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", 0, "vo_empress_104301_003", "マコト", "vo_empress_104301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104302, 152, 1, "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", 104301, "vo_empress_104301_004", "マコト", "vo_empress_104301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104401, 153, 1, "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", 0, "vo_empress_104401_001", "イリヤ", "vo_empress_104401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104401, 154, 1, "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", 0, "vo_empress_104401_002", "イリヤ", "vo_empress_104401_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104401, 155, 1, "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", 0, "vo_empress_104401_003", "イリヤ", "vo_empress_104401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104401, 156, 1, "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", 104401, "vo_empress_104401_004", "イリヤ", "vo_empress_104401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104501, 157, 1, "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", 0, "vo_empress_104501_001", "クウカ", "vo_empress_104501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104501, 158, 1, "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", 0, "vo_empress_104501_002", "クウカ", "vo_empress_104501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104503, 159, 1, "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", 0, "vo_empress_104501_003", "クウカ", "vo_empress_104501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104502, 160, 1, "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", 104501, "vo_empress_104501_004", "クウカ", "vo_empress_104501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104601, 161, 1, "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", 0, "vo_empress_104601_001", "タマキ", "vo_empress_104601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104601, 162, 1, "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", 0, "vo_empress_104601_002", "タマキ", "vo_empress_104601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104603, 163, 1, "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", 0, "vo_empress_104601_003", "タマキ", "vo_empress_104601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104602, 164, 1, "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", 104601, "vo_empress_104601_004", "タマキ", "vo_empress_104601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104701, 165, 1, "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", 0, "vo_empress_104701_001", "ジュン", "vo_empress_104701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104701, 166, 1, "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", 0, "vo_empress_104701_002", "ジュン", "vo_empress_104701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104701, 167, 1, "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", 0, "vo_empress_104701_003", "ジュン", "vo_empress_104701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104701, 168, 1, "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", 104701, "vo_empress_104701_004", "ジュン", "vo_empress_104701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104801, 169, 1, "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", 0, "vo_empress_104801_001", "ミフユ", "vo_empress_104801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104801, 170, 1, "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", 0, "vo_empress_104801_002", "ミフユ", "vo_empress_104801_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104803, 171, 1, "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", 0, "vo_empress_104801_003", "ミフユ", "vo_empress_104801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104802, 172, 1, "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", 104801, "vo_empress_104801_004", "ミフユ", "vo_empress_104801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104902, 173, 1, "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", 0, "vo_empress_104901_001", "シズル", "vo_empress_104901_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 104902, 174, 1, "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", 0, "vo_empress_104901_002", "シズル", "vo_empress_104901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 104903, 175, 1, "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", 0, "vo_empress_104901_003", "シズル", "vo_empress_104901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 104902, 176, 1, "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", 104901, "vo_empress_104901_004", "シズル", "vo_empress_104901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105001, 177, 1, "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", 0, "vo_empress_105001_001", "ミサキ", "vo_empress_105001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105001, 178, 1, "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", 0, "vo_empress_105001_002", "ミサキ", "vo_empress_105001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105003, 179, 1, "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", 0, "vo_empress_105001_003", "ミサキ", "vo_empress_105001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105002, 180, 1, "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", 105001, "vo_empress_105001_004", "ミサキ", "vo_empress_105001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105101, 181, 1, "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", 0, "vo_empress_105101_001", "ミツキ", "vo_empress_105101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105101, 182, 1, "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", 0, "vo_empress_105101_002", "ミツキ", "vo_empress_105101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105101, 183, 1, "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", 0, "vo_empress_105101_003", "ミツキ", "vo_empress_105101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105101, 184, 1, "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", 105101, "vo_empress_105101_004", "ミツキ", "vo_empress_105101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105201, 185, 1, "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", 0, "vo_empress_105201_001", "リマ", "vo_empress_105201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 105201, 186, 1, "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 0, "vo_empress_105201_002", "リマ", "vo_empress_105201_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105201, 187, 1, "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", 0, "vo_empress_105201_003", "リマ", "vo_empress_105201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105202, 188, 1, "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", 105201, "vo_empress_105201_004", "リマ", "vo_empress_105201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105303, 189, 1, "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", 0, "vo_empress_105301_001", "モニカ", "vo_empress_105301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105301, 190, 1, "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", 0, "vo_empress_105301_002", "モニカ", "vo_empress_105301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105301, 191, 1, "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", 0, "vo_empress_105301_003", "モニカ", "vo_empress_105301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105302, 192, 1, "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", 105301, "vo_empress_105301_004", "モニカ", "vo_empress_105301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105401, 193, 1, "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", 0, "vo_empress_105401_001", "ツムギ", "vo_empress_105401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 105403, 194, 1, "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 0, "vo_empress_105401_002", "ツムギ", "vo_empress_105401_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105403, 195, 1, "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", 0, "vo_empress_105401_003", "ツムギ", "vo_empress_105401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105401, 196, 1, "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", 105401, "vo_empress_105401_004", "ツムギ", "vo_empress_105401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105503, 197, 1, "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", 0, "vo_empress_105501_001", "アユミ", "vo_empress_105501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105501, 198, 1, "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", 0, "vo_empress_105501_002", "アユミ", "vo_empress_105501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105503, 199, 1, "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", 0, "vo_empress_105501_003", "アユミ", "vo_empress_105501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105502, 200, 1, "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", 105501, "vo_empress_105501_004", "アユミ", "vo_empress_105501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105601, 201, 1, "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", 0, "vo_empress_105601_001", "ルカ", "vo_empress_105601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105601, 202, 1, "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", 0, "vo_empress_105601_002", "ルカ", "vo_empress_105601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105603, 203, 1, "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", 0, "vo_empress_105601_003", "ルカ", "vo_empress_105601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105602, 204, 1, "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", 105601, "vo_empress_105601_004", "ルカ", "vo_empress_105601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105803, 205, 1, "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", 0, "vo_empress_105801_001", "ペコリーヌ", "vo_empress_105801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4003, 105801, 206, 1, "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 0, "vo_empress_105801_002", "ペコリーヌ", "vo_empress_105801_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105803, 207, 1, "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", 0, "vo_empress_105801_003", "ペコリーヌ", "vo_empress_105801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105802, 208, 1, "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", 105801, "vo_empress_105801_004", "ペコリーヌ", "vo_empress_105801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105903, 209, 1, "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", 0, "vo_empress_105901_001", "コッコロ", "vo_empress_105901_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 105905, 210, 1, "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", 0, "vo_empress_105901_002", "コッコロ", "vo_empress_105901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 105903, 211, 1, "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", 0, "vo_empress_105901_003", "コッコロ", "vo_empress_105901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 105902, 212, 1, "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", 105901, "vo_empress_105901_004", "コッコロ", "vo_empress_105901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 106001, 213, 1, "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 0, "vo_empress_106001_001", "キャル", "vo_empress_106001_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106003, 214, 1, "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", 0, "vo_empress_106001_002", "キャル", "vo_empress_106001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 106003, 215, 1, "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", 0, "vo_empress_106001_003", "キャル", "vo_empress_106001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 106002, 216, 1, "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", 106001, "vo_empress_106001_004", "キャル", "vo_empress_106001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106102, 217, 1, "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", 0, "vo_empress_106101_001", "ノウェム", "vo_empress_106101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106101, 218, 1, "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", 0, "vo_empress_106101_002", "ノウェム", "vo_empress_106101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 106103, 219, 1, "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", 0, "vo_empress_106101_003", "ノウェム", "vo_empress_106101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 106102, 220, 1, "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", 106101, "vo_empress_106101_004", "ノウェム", "vo_empress_106101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106401, 221, 1, "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", 0, "vo_empress_106401_001", "シェフィ", "vo_empress_106401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4004, 106403, 222, 1, "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 0, "vo_empress_106401_002", "シェフィ", "vo_empress_106401_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 106401, 223, 1, "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", 0, "vo_empress_106401_003", "シェフィ", "vo_empress_106401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 106402, 224, 1, "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", 106401, "vo_empress_106401_004", "シェフィ", "vo_empress_106401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106501, 225, 1, "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", 0, "vo_empress_106501_001", "カヤ", "vo_empress_106501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106501, 226, 1, "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", 0, "vo_empress_106501_002", "カヤ", "vo_empress_106501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 106503, 227, 1, "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", 0, "vo_empress_106501_003", "カヤ", "vo_empress_106501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 106501, 228, 1, "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", 106501, "vo_empress_106501_004", "カヤ", "vo_empress_106501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106603, 229, 1, "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", 0, "vo_empress_106601_001", "イノリ", "vo_empress_106601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106601, 230, 1, "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", 0, "vo_empress_106601_002", "イノリ", "vo_empress_106601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 106603, 231, 1, "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", 0, "vo_empress_106601_003", "イノリ", "vo_empress_106601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 106602, 232, 1, "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", 106601, "vo_empress_106601_004", "イノリ", "vo_empress_106601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106701, 233, 1, "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", 0, "vo_empress_106701_001", "ホマレ", "vo_empress_106701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106701, 234, 1, "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", 0, "vo_empress_106701_002", "ホマレ", "vo_empress_106701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 106703, 235, 1, "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", 0, "vo_empress_106701_003", "ホマレ", "vo_empress_106701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 106702, 236, 1, "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", 106701, "vo_empress_106701_004", "ホマレ", "vo_empress_106701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 106802, 237, 1, "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", 0, "vo_empress_106801_001", "ラビリスタ", "vo_empress_106801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 106801, 238, 1, "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 0, "vo_empress_106801_002", "ラビリスタ", "vo_empress_106801_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 106801, 239, 1, "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", 0, "vo_empress_106801_003", "ラビリスタ", "vo_empress_106801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 106802, 240, 1, "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", 106801, "vo_empress_106801_004", "ラビリスタ", "vo_empress_106801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 107001, 241, 1, "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 0, "vo_empress_107001_001", "ネネカ", "vo_empress_107001_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 107001, 242, 1, "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", 0, "vo_empress_107001_002", "ネネカ", "vo_empress_107001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 107001, 243, 1, "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", 0, "vo_empress_107001_003", "ネネカ", "vo_empress_107001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 107002, 244, 1, "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", 107001, "vo_empress_107001_004", "ネネカ", "vo_empress_107001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 107101, 245, 1, "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", 0, "vo_empress_107101_001", "クリスティーナ", "vo_empress_107101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 107101, 246, 1, "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 0, "vo_empress_107101_002", "クリスティーナ", "vo_empress_107101_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 107103, 247, 1, "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", 0, "vo_empress_107101_003", "クリスティーナ", "vo_empress_107101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 107102, 248, 1, "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", 107101, "vo_empress_107101_004", "クリスティーナ", "vo_empress_107101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 110801, 249, 1, "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", 0, "vo_empress_110801_001", "クロエ", "vo_empress_110801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 110801, 250, 1, "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 0, "vo_empress_110801_002", "クロエ", "vo_empress_110801_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 110803, 251, 1, "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", 0, "vo_empress_110801_003", "クロエ", "vo_empress_110801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 110802, 252, 1, "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", 110801, "vo_empress_110801_004", "クロエ", "vo_empress_110801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 110901, 253, 1, "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", 0, "vo_empress_110901_001", "チエル", "vo_empress_110901_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 110901, 254, 1, "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", 0, "vo_empress_110901_002", "チエル", "vo_empress_110901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 110903, 255, 1, "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", 0, "vo_empress_110901_003", "チエル", "vo_empress_110901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 110902, 256, 1, "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", 110901, "vo_empress_110901_004", "チエル", "vo_empress_110901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 111001, 257, 1, "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", 0, "vo_empress_111001_001", "ユニ", "vo_empress_111001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 111001, 258, 1, "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", 0, "vo_empress_111001_002", "ユニ", "vo_empress_111001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 111003, 259, 1, "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", 0, "vo_empress_111001_003", "ユニ", "vo_empress_111001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 111002, 260, 1, "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", 111001, "vo_empress_111001_004", "ユニ", "vo_empress_111001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118001, 261, 1, "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", 0, "vo_empress_118001_001", "クレジッタ", "vo_empress_118001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118003, 262, 1, "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", 0, "vo_empress_118001_002", "クレジッタ", "vo_empress_118001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 118003, 263, 1, "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", 0, "vo_empress_118001_003", "クレジッタ", "vo_empress_118001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 118002, 264, 1, "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", 118001, "vo_empress_118001_004", "クレジッタ", "vo_empress_118001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118101, 265, 1, "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", 0, "vo_empress_118101_001", "ランファ", "vo_empress_118101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118101, 266, 1, "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", 0, "vo_empress_118101_002", "ランファ", "vo_empress_118101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 118103, 267, 1, "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", 0, "vo_empress_118101_003", "ランファ", "vo_empress_118101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 118102, 268, 1, "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", 118101, "vo_empress_118101_004", "ランファ", "vo_empress_118101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 118201, 269, 1, "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 0, "vo_empress_118201_001", "ミソラ", "vo_empress_118201_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118201, 270, 1, "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", 0, "vo_empress_118201_002", "ミソラ", "vo_empress_118201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 118202, 271, 1, "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", 0, "vo_empress_118201_003", "ミソラ", "vo_empress_118201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 118202, 272, 1, "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", 118201, "vo_empress_118201_004", "ミソラ", "vo_empress_118201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118501, 273, 1, "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", 0, "vo_empress_118501_001", "カリン", "vo_empress_118501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118502, 274, 1, "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", 0, "vo_empress_118501_002", "カリン", "vo_empress_118501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 118503, 275, 1, "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", 0, "vo_empress_118501_003", "カリン", "vo_empress_118501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 118502, 276, 1, "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", 118501, "vo_empress_118501_004", "カリン", "vo_empress_118501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118601, 277, 1, "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", 0, "vo_empress_118601_001", "ネビア", "vo_empress_118601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 118601, 278, 1, "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", 0, "vo_empress_118601_002", "ネビア", "vo_empress_118601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 118603, 279, 1, "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", 0, "vo_empress_118601_003", "ネビア", "vo_empress_118601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 118602, 280, 1, "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", 118601, "vo_empress_118601_004", "ネビア", "vo_empress_118601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 122303, 281, 1, "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", 0, "vo_empress_122301_001", "ヴァンピィ", "vo_empress_122301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 122302, 282, 1, "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", 0, "vo_empress_122301_002", "ヴァンピィ", "vo_empress_122301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 122303, 283, 1, "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", 0, "vo_empress_122301_003", "ヴァンピィ", "vo_empress_122301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 122302, 284, 1, "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", 122301, "vo_empress_122301_004", "ヴァンピィ", "vo_empress_122301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 123002, 285, 1, "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", 0, "vo_empress_123001_001", "アメス", "vo_empress_123001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 123001, 286, 1, "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", 0, "vo_empress_123001_002", "アメス", "vo_empress_123001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 123003, 287, 1, "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", 0, "vo_empress_123001_003", "アメス", "vo_empress_123001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 123002, 288, 1, "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", 123001, "vo_empress_123001_004", "アメス", "vo_empress_123001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 123301, 289, 1, "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", 0, "vo_empress_123301_001", "ネア", "vo_empress_123301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 123301, 290, 1, "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", 0, "vo_empress_123301_002", "ネア", "vo_empress_123301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 123303, 291, 1, "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", 0, "vo_empress_123301_003", "ネア", "vo_empress_123301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 123302, 292, 1, "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", 123301, "vo_empress_123301_004", "ネア", "vo_empress_123301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 126401, 293, 1, "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", 0, "vo_empress_126401_001", "クローチェ", "vo_empress_126401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 126401, 294, 1, "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", 0, "vo_empress_126401_002", "クローチェ", "vo_empress_126401_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 126403, 295, 1, "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", 0, "vo_empress_126401_003", "クローチェ", "vo_empress_126401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 126402, 296, 1, "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", 126401, "vo_empress_126401_004", "クローチェ", "vo_empress_126401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 126501, 297, 1, "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", 0, "vo_empress_126501_001", "ライラエル", "vo_empress_126501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 126506, 298, 1, "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 0, "vo_empress_126501_002", "ライラエル", "vo_empress_126501_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 126503, 299, 1, "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", 0, "vo_empress_126501_003", "ライラエル", "vo_empress_126501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 126502, 300, 1, "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", 126501, "vo_empress_126501_004", "ライラエル", "vo_empress_126501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 127701, 301, 1, "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 0, "vo_empress_127701_001", "リンド", "vo_empress_127701_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 127701, 302, 1, "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", 0, "vo_empress_127701_002", "リンド", "vo_empress_127701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 127703, 303, 1, "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", 0, "vo_empress_127701_003", "リンド", "vo_empress_127701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 127702, 304, 1, "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", 127701, "vo_empress_127701_004", "リンド", "vo_empress_127701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 127801, 305, 1, "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", 0, "vo_empress_127801_001", "ヴルム", "vo_empress_127801_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 127801, 306, 1, "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 0, "vo_empress_127801_002", "ヴルム", "vo_empress_127801_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 127803, 307, 1, "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", 0, "vo_empress_127801_003", "ヴルム", "vo_empress_127801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 127802, 308, 1, "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", 127801, "vo_empress_127801_004", "ヴルム", "vo_empress_127801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 129001, 309, 1, "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 0, "vo_empress_129001_001", "エリス", "vo_empress_129001_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 129001, 310, 1, "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", 0, "vo_empress_129001_002", "エリス", "vo_empress_129001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 129003, 311, 1, "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", 0, "vo_empress_129001_003", "エリス", "vo_empress_129001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 129002, 312, 1, "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", 129001, "vo_empress_129001_004", "エリス", "vo_empress_129001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 129601, 313, 1, "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", 0, "vo_empress_129601_001", "アネモネ", "vo_empress_129601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 129601, 314, 1, "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", 0, "vo_empress_129601_002", "アネモネ", "vo_empress_129601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 129603, 315, 1, "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", 0, "vo_empress_129601_003", "アネモネ", "vo_empress_129601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 129601, 316, 1, "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", 129601, "vo_empress_129601_004", "アネモネ", "vo_empress_129601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 129701, 317, 1, "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", 0, "vo_empress_129701_001", "ネフィ＝ネラ", "vo_empress_129701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 129701, 318, 1, "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", 0, "vo_empress_129701_002", "ネフィ＝ネラ", "vo_empress_129701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 129703, 319, 1, "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", 0, "vo_empress_129701_003", "ネフィ＝ネラ", "vo_empress_129701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 129702, 320, 1, "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", 129701, "vo_empress_129701_004", "ネフィ＝ネラ", "vo_empress_129701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4003, 130001, 321, 1, "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 0, "vo_empress_130001_001", "ヤマト", "vo_empress_130001_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 130001, 322, 1, "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", 0, "vo_empress_130001_002", "ヤマト", "vo_empress_130001_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 130003, 323, 1, "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", 0, "vo_empress_130001_003", "ヤマト", "vo_empress_130001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 130002, 324, 1, "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", 130001, "vo_empress_130001_004", "ヤマト", "vo_empress_130001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 130101, 325, 1, "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", 0, "vo_empress_130101_001", "ワカナ", "vo_empress_130101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 130101, 326, 1, "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", 0, "vo_empress_130101_002", "ワカナ", "vo_empress_130101_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 130103, 327, 1, "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", 0, "vo_empress_130101_003", "ワカナ", "vo_empress_130101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 130102, 328, 1, "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", 130101, "vo_empress_130101_004", "ワカナ", "vo_empress_130101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 130201, 329, 1, "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", 0, "vo_empress_130201_001", "フブキ", "vo_empress_130201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 130201, 330, 1, "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", 0, "vo_empress_130201_002", "フブキ", "vo_empress_130201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 130203, 331, 1, "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", 0, "vo_empress_130201_003", "フブキ", "vo_empress_130201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 130202, 332, 1, "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", 130201, "vo_empress_130201_004", "フブキ", "vo_empress_130201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 130901, 333, 1, "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", 0, "vo_empress_130901_001", "クルル", "vo_empress_130901_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 130901, 334, 1, "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", 0, "vo_empress_130901_002", "クルル", "vo_empress_130901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 130903, 335, 1, "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", 0, "vo_empress_130901_003", "クルル", "vo_empress_130901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 130902, 336, 1, "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", 130901, "vo_empress_130901_004", "クルル", "vo_empress_130901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 132301, 337, 1, "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", 0, "vo_empress_132301_001", "ルイズマリー", "vo_empress_132301_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 132301, 338, 1, "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", 0, "vo_empress_132301_002", "ルイズマリー", "vo_empress_132301_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 132303, 339, 1, "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", 0, "vo_empress_132301_003", "ルイズマリー", "vo_empress_132301_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 132302, 340, 1, "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", 132301, "vo_empress_132301_004", "ルイズマリー", "vo_empress_132301_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 132401, 341, 1, "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", 0, "vo_empress_132401_001", "イロハ", "vo_empress_132401_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 132401, 342, 1, "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", 0, "vo_empress_132401_002", "イロハ", "vo_empress_132401_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 132401, 343, 1, "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", 0, "vo_empress_132401_003", "イロハ", "vo_empress_132401_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 132402, 344, 1, "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", 132401, "vo_empress_132401_004", "イロハ", "vo_empress_132401_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 132501, 345, 1, "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", 0, "vo_empress_132501_001", "ソノ", "vo_empress_132501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 132501, 346, 1, "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", 0, "vo_empress_132501_002", "ソノ", "vo_empress_132501_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 132503, 347, 1, "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", 0, "vo_empress_132501_003", "ソノ", "vo_empress_132501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 132502, 348, 1, "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", 132501, "vo_empress_132501_004", "ソノ", "vo_empress_132501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 133001, 349, 1, "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", 0, "vo_empress_133001_001", "グレイス", "vo_empress_133001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, 133003, 350, 1, "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 0, "vo_empress_133001_002", "グレイス", "vo_empress_133001_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 133003, 351, 1, "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", 0, "vo_empress_133001_003", "グレイス", "vo_empress_133001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 133002, 352, 1, "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", 133001, "vo_empress_133001_004", "グレイス", "vo_empress_133001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 133101, 353, 1, "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", 0, "vo_empress_133101_001", "ヴァイオレット", "vo_empress_133101_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, 133101, 354, 1, "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 0, "vo_empress_133101_002", "ヴァイオレット", "vo_empress_133101_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 133103, 355, 1, "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", 0, "vo_empress_133101_003", "ヴァイオレット", "vo_empress_133101_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 133102, 356, 1, "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", 133101, "vo_empress_133101_004", "ヴァイオレット", "vo_empress_133101_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 133601, 357, 1, "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", 0, "vo_empress_133601_001", "メドゥーサ", "vo_empress_133601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 133601, 358, 1, "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", 0, "vo_empress_133601_002", "メドゥーサ", "vo_empress_133601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 133603, 359, 1, "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", 0, "vo_empress_133601_003", "メドゥーサ", "vo_empress_133601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 133602, 360, 1, "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", 133601, "vo_empress_133601_004", "メドゥーサ", "vo_empress_133601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 134701, 361, 1, "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", 0, "vo_empress_134701_001", "ホウオウ", "vo_empress_134701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 134701, 362, 1, "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", 0, "vo_empress_134701_002", "ホウオウ", "vo_empress_134701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 134703, 363, 1, "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", 0, "vo_empress_134701_003", "ホウオウ", "vo_empress_134701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 134702, 364, 1, "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", 134701, "vo_empress_134701_004", "ホウオウ", "vo_empress_134701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 134901, 365, 1, "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", 0, "vo_empress_134901_001", "カノン", "vo_empress_134901_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 134901, 366, 1, "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", 0, "vo_empress_134901_002", "カノン", "vo_empress_134901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 134903, 367, 1, "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", 0, "vo_empress_134901_003", "カノン", "vo_empress_134901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 134902, 368, 1, "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", 134901, "vo_empress_134901_004", "カノン", "vo_empress_134901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 135501, 369, 1, "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", 0, "vo_empress_135501_001", "アイラ", "vo_empress_135501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, 135501, 370, 1, "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 0, "vo_empress_135501_002", "アイラ", "vo_empress_135501_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 135503, 371, 1, "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", 0, "vo_empress_135501_003", "アイラ", "vo_empress_135501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 135502, 372, 1, "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", 135501, "vo_empress_135501_004", "アイラ", "vo_empress_135501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 135601, 373, 1, "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", 0, "vo_empress_135601_001", "シナツ", "vo_empress_135601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 135601, 374, 1, "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", 0, "vo_empress_135601_002", "シナツ", "vo_empress_135601_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 135603, 375, 1, "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", 0, "vo_empress_135601_003", "シナツ", "vo_empress_135601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 135602, 376, 1, "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", 135601, "vo_empress_135601_004", "シナツ", "vo_empress_135601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, 135801, 377, 1, "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 0, "vo_empress_135801_001", "ユキノ", "vo_empress_135801_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 135801, 378, 1, "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", 0, "vo_empress_135801_002", "ユキノ", "vo_empress_135801_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 135803, 379, 1, "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", 0, "vo_empress_135801_003", "ユキノ", "vo_empress_135801_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 135802, 380, 1, "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", 135801, "vo_empress_135801_004", "ユキノ", "vo_empress_135801_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, 135903, 381, 1, "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 0, "vo_empress_135901_001", "サツキ", "vo_empress_135901_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 135901, 382, 1, "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", 0, "vo_empress_135901_002", "サツキ", "vo_empress_135901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 135901, 383, 1, "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", 0, "vo_empress_135901_003", "サツキ", "vo_empress_135901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 135902, 384, 1, "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", 135901, "vo_empress_135901_004", "サツキ", "vo_empress_135901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 136001, 385, 1, "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", 0, "vo_empress_136001_001", "アラクネ", "vo_empress_136001_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4003, 136001, 386, 1, "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 0, "vo_empress_136001_002", "アラクネ", "vo_empress_136001_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 136003, 387, 1, "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", 0, "vo_empress_136001_003", "アラクネ", "vo_empress_136001_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 136002, 388, 1, "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", 136001, "vo_empress_136001_004", "アラクネ", "vo_empress_136001_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 136201, 389, 1, "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", 0, "vo_empress_136201_001", "ナーナ", "vo_empress_136201_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 136201, 390, 1, "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", 0, "vo_empress_136201_002", "ナーナ", "vo_empress_136201_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 136201, 391, 1, "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", 0, "vo_empress_136201_003", "ナーナ", "vo_empress_136201_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 136202, 392, 1, "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", 136201, "vo_empress_136201_004", "ナーナ", "vo_empress_136201_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, 136903, 393, 1, "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 0, "vo_empress_136901_001", "ルルィ", "vo_empress_136901_001", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 136901, 394, 1, "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", 0, "vo_empress_136901_002", "ルルィ", "vo_empress_136901_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 136903, 395, 1, "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", 0, "vo_empress_136901_003", "ルルィ", "vo_empress_136901_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 136902, 396, 1, "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", 136901, "vo_empress_136901_004", "ルルィ", "vo_empress_136901_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 139501, 397, 1, "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", 0, "vo_empress_139501_001", "リリ", "vo_empress_139501_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 139503, 398, 1, "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 0, "vo_empress_139501_002", "リリ", "vo_empress_139501_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 139503, 399, 1, "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", 0, "vo_empress_139501_003", "リリ", "vo_empress_139501_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 139502, 400, 1, "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", 125801, "vo_empress_139501_004", "リリ", "vo_empress_139501_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 139603, 401, 1, "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", 0, "vo_empress_139601_001", "クリア", "vo_empress_139601_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, 139603, 402, 1, "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 0, "vo_empress_139601_002", "クリア", "vo_empress_139601_002", 1, 3, 10000, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 139603, 403, 1, "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", 0, "vo_empress_139601_003", "クリア", "vo_empress_139601_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 139601, 404, 1, "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", 126001, "vo_empress_139601_004", "クリア", "vo_empress_139601_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 139701, 405, 1, "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", 0, "vo_empress_139701_001", "プレシア", "vo_empress_139701_001", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, 139701, 406, 1, "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", 0, "vo_empress_139701_002", "プレシア", "vo_empress_139701_002", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, 139703, 407, 1, "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", 0, "vo_empress_139701_003", "プレシア", "vo_empress_139701_003", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 139702, 408, 1, "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", 126101, "vo_empress_139701_004", "プレシア", "vo_empress_139701_004", "", 5, "", 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, 140301, 409, 1, "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", 140301, "vo_empress_140301_004", "ティア", "vo_empress_140301_004", "", 5, "", 4);
